df['月均销量']=df['年销量']/12
def turnover(row):
    if row['月均销量']>0:
        return int(round(row['期末库存']/row['月均销量']*30))
    return 999
df['周转天数']=df.apply(turnover,axis=1)
avg_turnover_days=int(df['周转天数'].mean())
overstock=df[df['周转天数']>180]
overstock_count=int(len(overstock))
overstock_value=int((overstock['期末库存']*overstock['销售单价']).sum())
